test "lower-c source map records defer cleanup spans" {
    const source =
        \\extern fn close_resource() -> void;
        \\
        \\fn cleanup(flag: bool) -> void {
        \\    defer close_resource();
        \\    defer {
        \\        close_resource();
        \\    };
        \\    while flag {
        \\        defer close_resource();
