        \\    let ptrs: [2]*mut u32 = .{ &shared_counter, &shared_counter };
        \\    #[unsafe_contract(noalias)]
        \\    {
        \\        let p: *mut u32 = compiler.assume_noalias_unchecked(ptrs[0], 4) as *mut u32;
        \\        return p.*;
