test "lower-c emits lexical defer cleanup before return" {
    const source =
        \\extern fn close_a() -> void;
        \\extern fn close_b() -> void;
        \\fn accept_lexical_cleanup() -> void {
        \\    defer close_a();
        \\    defer close_b();
        \\    return;
        \\}
        \\fn accept_block_cleanup() -> void {
        \\    defer { close_a(); };
        \\    return;
        \\}
        \\fn accept_cleanup_before_break(flag: bool) -> void {
        \\    while flag { defer close_a(); break; }
        \\}
        \\fn accept_cleanup_before_continue(flag: bool) -> void {
        \\    while flag { defer close_a(); continue; }
        \\}
        \\fn accept_cleanup_on_fallthrough() -> void { defer close_a(); }
    ;
    var output: std.ArrayList(u8) = .empty;
    defer output.deinit(std.testing.allocator);
    try appendCTest("emit_c_defer.mc", source, &output);
    try std.testing.expect(std.mem.indexOf(u8, output.items, "void close_a(void);") != null);
    try std.testing.expect(std.mem.indexOf(u8, output.items, "void close_b(void);") != null);
    try std.testing.expect(std.mem.indexOf(u8, output.items, "MC_UNUSED static void accept_lexical_cleanup(void) {\n    close_b();\n    close_a();\n    return;\n}") != null);
    try std.testing.expect(std.mem.indexOf(u8, output.items, "MC_UNUSED static void accept_block_cleanup(void) {\n    {\n        close_a();\n    }\n    return;\n}") != null);
    try std.testing.expect(std.mem.indexOf(u8, output.items, "MC_UNUSED static void accept_cleanup_before_break(bool flag) {\n    while (flag) {\n        close_a();\n        goto mc_break_") != null);
    try std.testing.expect(std.mem.indexOf(u8, output.items, "MC_UNUSED static void accept_cleanup_before_continue(bool flag) {\n    while (flag) {\n        close_a();\n        goto mc_continue_") != null);
    try std.testing.expect(std.mem.indexOf(u8, output.items, "MC_UNUSED static void accept_cleanup_on_fallthrough(void) {\n    close_a();\n}") != null);
}

test "lower-c emits deferred drop-attribute pointer release before return" {
    const source =
        \\move struct Ticket { id: u32 }
        \\fn issue_ticket() -> Ticket { return .{ .id = 1 }; }
        \\#[drop]
        \\fn close_ticket(t: *mut Ticket) -> void { t.id = 0; }
        \\fn accept_deferred_resource_release(flag: bool) -> u32 {
        \\    var t: Ticket = issue_ticket();
        \\    defer close_ticket(&t);
        \\    if flag {
        \\        return 1;
        \\    }
        \\    return 2;
        \\}
    ;
    var output: std.ArrayList(u8) = .empty;
    defer output.deinit(std.testing.allocator);
    try appendCTest("emit_c_drop_attr_defer.mc", source, &output);
    const body = try cFunctionBody(output.items, "static uint32_t accept_deferred_resource_release(bool flag)");
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, body, "close_ticket("));
    try std.testing.expectEqual(@as(usize, 2), std.mem.count(u8, body, "uint32_t mc_tmp"));
    const first_cleanup = std.mem.indexOf(u8, body, "close_ticket(").?;
    const early_value = std.mem.indexOf(u8, body, "uint32_t mc_tmp").?;
    const early_return = std.mem.indexOf(u8, body, "return mc_tmp").?;
    const final_cleanup = std.mem.lastIndexOf(u8, body, "close_ticket(").?;
    const final_value = std.mem.lastIndexOf(u8, body, "uint32_t mc_tmp").?;
    const final_return = std.mem.lastIndexOf(u8, body, "return mc_tmp").?;
    try std.testing.expect(early_value < first_cleanup);
    try std.testing.expect(first_cleanup < early_return);
    try std.testing.expect(final_value < final_cleanup);
    try std.testing.expect(final_cleanup < final_return);
}

test "lower-c deferred drop release requires source-matched MIR explicit-drop event" {
    const source =
        \\move struct Ticket { id: u32 }
        \\fn issue_ticket() -> Ticket { return .{ .id = 1 }; }
        \\#[drop]
        \\fn close_ticket(t: *mut Ticket) -> void { t.id = 0; }
        \\fn accept_deferred_resource_release() -> void {
        \\    var t: Ticket = issue_ticket();
        \\    defer close_ticket(&t);
        \\    return;
        \\}
    ;
    var parsed = try test_support.parseModule("emit_c_drop_attr_defer_source_requires_event.mc", source);
    defer parsed.deinit();

    var module_mir = try mir.buildFromDecls(std.testing.allocator, parsed.decls());
    defer module_mir.deinit();
    const function = for (module_mir.functions) |*candidate| {
        if (std.mem.eql(u8, candidate.name, "accept_deferred_resource_release")) break candidate;
    } else return error.TestUnexpectedResult;
    for (function.ownership_events) |*event| {
        if (event.kind == .explicit_drop) {
            event.source.line += 1;
            break;
        }
    } else return error.TestUnexpectedResult;
    try mir.validateLoweringAdmission(module_mir);

    var output: std.ArrayList(u8) = .empty;
    defer output.deinit(std.testing.allocator);
    try std.testing.expectError(error.UnsupportedCEmission, appendCProfileWithMirDeclsTest(std.testing.allocator, parsed.decls(), &module_mir, &output, .kernel, "emit_c_drop_attr_defer_source_requires_event.mc", .{}, false, null));
}

