}

test "lower-c consumes MIR drop glue facts and fails closed when absent or stale" {
    const source =
        \\move struct Guard { id: u32 }
        \\fn make_guard() -> Guard { return .{ .id = 1 }; }
        \\#[drop]
        \\fn close_guard(g: *mut Guard) -> void { g.id = 0; }
        \\fn auto_drop_from_mir_fact() -> u32 {
        \\    var g = make_guard();
        \\    return g.id;
        \\}
    ;
    var parsed = try test_support.parseModule("c_drop_glue_mir_facts.mc", source);
    defer parsed.deinit();

    var module_mir = try mir.buildFromDecls(std.testing.allocator, parsed.decls());
    defer module_mir.deinit();
    try std.testing.expectEqual(@as(usize, 1), module_mir.drop_glue_facts.len);
    try std.testing.expectEqual(@as(usize, 1), module_mir.type_ownership_facts.len);

    var valid_output: std.ArrayList(u8) = .empty;
    defer valid_output.deinit(std.testing.allocator);
    try appendCProfileWithMirDeclsTest(std.testing.allocator, parsed.decls(), &module_mir, &valid_output, .kernel, "c_drop_glue_mir_facts.mc", .{}, false, null);
    try expectContains(valid_output.items, "close_guard(&g);");

    const saved_events = for (module_mir.functions) |*function| {
        if (std.mem.eql(u8, function.name, "auto_drop_from_mir_fact")) {
            const saved = function.ownership_events;
            function.ownership_events = &[_]mir.OwnershipEvent{};
            break saved;
        }
    } else return error.TestUnexpectedResult;
    var missing_auto_drop_event_output: std.ArrayList(u8) = .empty;
    defer missing_auto_drop_event_output.deinit(std.testing.allocator);
    try std.testing.expectError(error.UnsupportedCEmission, appendCProfileWithMirDeclsTest(std.testing.allocator, parsed.decls(), &module_mir, &missing_auto_drop_event_output, .kernel, "c_drop_glue_mir_facts.mc", .{}, false, null));
    for (module_mir.functions) |*function| {
        if (std.mem.eql(u8, function.name, "auto_drop_from_mir_fact")) {
            function.ownership_events = saved_events;
            break;
        }
    }

    const saved_ownership_facts = module_mir.type_ownership_facts;
    module_mir.type_ownership_facts = &[_]mir.TypeOwnershipFact{};
    var missing_ownership_output: std.ArrayList(u8) = .empty;
    defer missing_ownership_output.deinit(std.testing.allocator);
    try std.testing.expectError(error.InvalidMirDropGlueFacts, appendCProfileWithMirDeclsTest(std.testing.allocator, parsed.decls(), &module_mir, &missing_ownership_output, .kernel, "c_drop_glue_mir_facts.mc", .{}, false, null));
    module_mir.type_ownership_facts = saved_ownership_facts;

    const saved_kind = module_mir.type_ownership_facts[0].kind;
    module_mir.type_ownership_facts[0].kind = .copy;
    var stale_ownership_output: std.ArrayList(u8) = .empty;
    defer stale_ownership_output.deinit(std.testing.allocator);
    try std.testing.expectError(error.InvalidMirDropGlueFacts, appendCProfileWithMirDeclsTest(std.testing.allocator, parsed.decls(), &module_mir, &stale_ownership_output, .kernel, "c_drop_glue_mir_facts.mc", .{}, false, null));
    module_mir.type_ownership_facts[0].kind = saved_kind;

    const make_guard_symbol = for (module_mir.functions) |function| {
        if (std.mem.eql(u8, function.name, "make_guard")) break function.typed_symbol_id;
    } else return error.TestUnexpectedResult;

    const saved_ownership_drop_symbol = module_mir.type_ownership_facts[0].drop_glue_symbol_id;
    module_mir.type_ownership_facts[0].drop_glue_symbol_id = make_guard_symbol;
    var stale_ownership_symbol_output: std.ArrayList(u8) = .empty;
    defer stale_ownership_symbol_output.deinit(std.testing.allocator);
    try std.testing.expectError(error.InvalidMirDropGlueFacts, appendCProfileWithMirDeclsTest(std.testing.allocator, parsed.decls(), &module_mir, &stale_ownership_symbol_output, .kernel, "c_drop_glue_mir_facts.mc", .{}, false, null));
    module_mir.type_ownership_facts[0].drop_glue_symbol_id = saved_ownership_drop_symbol;

    const saved_facts = module_mir.drop_glue_facts;
    module_mir.drop_glue_facts = &[_]mir.DropGlueFact{};
    var missing_output: std.ArrayList(u8) = .empty;
    defer missing_output.deinit(std.testing.allocator);
    try std.testing.expectError(error.InvalidMirTypeOwnershipFacts, appendCProfileWithMirDeclsTest(std.testing.allocator, parsed.decls(), &module_mir, &missing_output, .kernel, "c_drop_glue_mir_facts.mc", .{}, false, null));
    module_mir.drop_glue_facts = saved_facts;

    const saved_fn = module_mir.drop_glue_facts[0].release_fn;
    const saved_symbol = module_mir.drop_glue_facts[0].typed_release_symbol_id;
    module_mir.drop_glue_facts[0].release_fn = "make_guard";
    module_mir.drop_glue_facts[0].typed_release_symbol_id = make_guard_symbol;
    defer {
        module_mir.drop_glue_facts[0].release_fn = saved_fn;
        module_mir.drop_glue_facts[0].typed_release_symbol_id = saved_symbol;
    }
    var stale_output: std.ArrayList(u8) = .empty;
    defer stale_output.deinit(std.testing.allocator);
    try std.testing.expectError(error.InvalidMirDropGlueFacts, appendCProfileWithMirDeclsTest(std.testing.allocator, parsed.decls(), &module_mir, &stale_output, .kernel, "c_drop_glue_mir_facts.mc", .{}, false, null));
}

